Fixes: 7eb9282cd0ef ("netfilter: ipt_LOG/ip6t_LOG: add option to print decoded MAC header")
Reported-by: Weiming Shi <bestswngs@gmail.com>
Assisted-by: Claude:claude-opus-4-8
Signed-off-by: Xiang Mei <xmei5@asu.edu>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The fallback path in dump_mac_header() used `skb->mac_header != skb->network_header` to decide whether to dump the MAC header, but did not check `skb_mac_header_was_set()`. When the MAC header is unset (e.g., in AF_PACKET with PACKET_QDISC_BYPASS), mac_header is 0xffff, passing the condition and causing an out-of-bounds read of up to dev->hard_header_len bytes.

Here is the patch:

 static void dump_mac_header(struct nf_log_buf *m,
 			    const struct nf_loginfo *info,
 			    const struct sk_buff *skb)
 {
 	struct net_device *dev = skb->dev;
 	unsigned int logflags = 0;

 	if (info->type == NF_LOG_TYPE_LOG)
 		logflags = info->u.log.logflags;

 	if (!(logflags & NF_LOG_MACDECODE))
 		goto fallback;

 	switch (dev->type) {
 	case ARPHRD_ETHER:
 		if (!skb_mac_header_was_set(skb) || skb_mac_header_len(skb) < ETH_HLEN)
 			return;

 		nf_log_buf_add(m, "MACSRC=%pM MACDST=%pM ",
 			       eth_hdr(skb)->h_source, eth_hdr(skb)->h_dest);
 		nf_log_dump_vlan(m, skb);
 		nf_log_buf_add(m, "MACPROTO=%04x ",
 			       ntohs(eth_hdr(skb)->h_proto));
 		return;
 	default:
 		break;
 	}

 fallback:
 	nf_log_buf_add(m, "MAC=");
-	if (dev->hard_header_len &&
-	    skb->mac_header != skb->network_header) {
+	if (dev->hard_header_len && skb_mac_header_was_set(skb) &&
+	    skb_mac_header_len(skb) != 0) {
 		const unsigned char *p = skb_mac_header(skb);
 		unsigned int i;

 		if (dev->type == ARPHRD_SIT) {
 			p -= ETH_HLEN;

 			if (p < skb->head)
 				p = NULL;
 		}

 		if (p) {
 			nf_log_buf_add(m, "%02x", *p++);
 			for (i = 1; i < dev->hard_header_len; i++)
 				nf_log_buf_add(m, ":%02x", *p++);
 		}

 		if (dev->type == ARPHRD_SIT) {
 			const struct iphdr *iph =
 				(struct iphdr *)skb_mac_header(skb);

 			nf_log_buf_add(m, " TUNNEL=%pI4->%pI4", &iph->saddr,
 				       &iph->daddr);
 		}
 	}
 	nf_log_buf_add(m, " ");
 }



